const initial=seed();let state,storageOk=true,selected=null,mode='select',connectStart=null,sceneScale=1,gesture=null,suppressClick=false,toastTimer,modalFocus=null,editSnapshot=null;
function validate(s){return !!(s&&s.version===2&&s.docs&&s.boards&&s.boards.home&&s.boards[s.currentBoard]&&Object.values(s.boards).every(b=>Array.isArray(b.nodes)&&Array.isArray(b.edges)&&b.view&&b.nodes.every(n=>Number.isFinite(n.x)&&Number.isFinite(n.y)&&(!n.doc||s.docs[n.doc])&&(!n.board||s.boards[n.board]))));}
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):clone(initial);if(!validate(state))state=clone(initial);}catch(_){state=clone(initial);storageOk=false;}
Object.values(state.boards).forEach(b=>{if(b.iconStatus==='generating'){b.iconStatus='failed';b.iconError='上次生成会话已中断，可重新生成图标。';}});
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOk=true;}catch(_){storageOk=false;}}
const board=()=>state.boards[state.currentBoard], node=()=>board().nodes.find(n=>n.id===selected);
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600);}
function fit(){sceneScale=Math.min(innerWidth/1536,innerHeight/1024);$('scene').style.transform=`scale(${sceneScale})`;$('scene').style.left=(innerWidth-1536*sceneScale)/2+'px';$('scene').style.top=(innerHeight-1024*sceneScale)/2+'px';}
function children(id){return Object.values(state.boards).filter(b=>b.parent===id);}
function path(id){const arr=[],seen=new Set();while(state.boards[id]&&!seen.has(id)){seen.add(id);arr.unshift(state.boards[id]);id=state.boards[id].parent;}return arr;}
function descendant(target,ancestor){const seen=new Set();while(target&&state.boards[target]&&!seen.has(target)){if(target===ancestor)return true;seen.add(target);target=state.boards[target].parent;}return false;}
function counts(id){const b=state.boards[id];return {boards:b.nodes.filter(n=>n.type==='board').length,cards:b.nodes.filter(n=>n.type!=='board').length};}
function themeArt(theme,b){if(b?.iconUrl)return `<div class="folder-art custom-folder"><img src="${esc(b.iconUrl)}" alt="${esc(b.title)}的图标">${b.iconStatus==='generating'?'<span class="icon-loading">正在生成…</span>':''}</div>`;if(b?.iconId||b?.iconMode)return defaultFolder(b.title,b.iconId,b.iconStatus); return `<div class="folder-art ${themes.includes(theme)?theme:'product'}" aria-hidden="true"></div>`;}
function strip(body){return body.replace(/^# .*\n?/,'').replace(/^#+ /gm,'').replace(/\[\[([^\]]+)\]\]/g,'$1').trim();}
function render(){const b=board();$('board-title').textContent=b.title;$('subtitle').textContent=b.id==='home'?'把文章收进画板，让思考有层次。':b.id==='research'?'把观察、访谈和洞察放在一起。':'把线索放在这里，给下一层留一点空间。';$('crumbs').innerHTML=path(b.id).map(p=>`<span>›</span><button data-nav="${esc(p.id)}" data-testid="crumb-${esc(p.id)}">${esc(p.title)}</button>`).join('');$('scene').classList.toggle('research-scene',b.id==='research');$('nodes').innerHTML=b.nodes.map(n=>{const actions=`<div class="node-actions"><button data-select="${esc(n.id)}" aria-label="选择卡片" data-testid="select-${esc(n.id)}">✓</button><button data-move="${esc(n.id)}" aria-label="移动这张卡片">↗</button></div>`;if(n.type==='board'){const sub=state.boards[n.board],c=counts(sub.id);return `<div class="node folder ${selected===n.id?'selected':''}" style="left:${n.x}px;top:${n.y}px" data-node="${esc(n.id)}" data-testid="folder-${esc(sub.id)}" tabindex="0" role="group" aria-label="画板 ${esc(sub.title)}">${actions}${themeArt(sub.theme,sub)}<button class="folder-name" data-nav="${esc(sub.id)}" data-testid="open-board-${esc(sub.id)}" aria-label="进入 ${esc(sub.title)}">${esc(sub.title)}</button><div class="folder-meta"><span>${c.boards?c.boards+' boards · ':''}${c.cards} cards</span></div></div>`;}if(n.type==='photo')return `<div class="node photo ${selected===n.id?'selected':''}" style="left:${n.x}px;top:${n.y}px" data-node="${esc(n.id)}" tabindex="0" role="button" aria-label="灵感图片：Better People Better Products">${actions}</div>`;if(n.type==='note')return `<div class="node sticky ${n.color||''} ${selected===n.id?'selected':''}" style="left:${n.x}px;top:${n.y}px;${n.w?'width:'+n.w+'px;':''}${n.h?'height:'+n.h+'px;':''}transform:rotate(${n.angle||0}deg)" data-node="${esc(n.id)}" tabindex="0" role="button" aria-label="便利贴 ${esc(n.title)}">${actions}<h2>${esc(n.title)}</h2><div class="excerpt">${esc(n.text)}</div></div>`;const d=state.docs[n.doc],t=n.large?strip(d.body).replace(/\n{2,}/g,'\n'):strip(d.body);return `<div class="node paper ${n.homeNote?'home-note':''} ${n.large?'large-paper':''} ${selected===n.id?'selected':''}" style="left:${n.x}px;top:${n.y}px;${n.w?'width:'+n.w+'px;':''}${n.h?'height:'+n.h+'px;':''}transform:rotate(${n.angle||0}deg)" data-node="${esc(n.id)}" data-testid="article-${esc(n.id)}" tabindex="0" role="button" aria-label="查看文章 ${esc(d.title)}">${actions}<div class="date">${n.date|| (n.homeNote?(n.id==='reminder'?'2024.11.28':'2024.11.27'):'MARKDOWN · 示例')}</div><h2><span class="highlight">${esc(d.title)}</span></h2><div class="excerpt">${n.id==='focus'?t.split('\n').map(line=>`<span class="check ${line.startsWith('☑')?'checked':''}">${line.startsWith('☑')?'✓':''}</span>${esc(line.replace(/^[□☑] /,''))}`).join('<br>'):esc(t)}</div>${!n.homeNote&&!n.large?'<span class="source">同一原文 · '+esc(d.path)+'</span>':''}</div>`;}).join('');$('empty').innerHTML=b.nodes.length?'':`<h2>一个新的思考空间</h2><p>放进一篇文章，或创建子画板。<br>每一层都可以继续深入。</p><button class="btn" data-action="article">＋ 添加文章</button><button class="btn" data-action="board">＋ 新建子画板</button>`;applyView();renderEdges();renderSelection();$('mode-banner').textContent=mode==='connect'?(connectStart?'再选择一张卡片，建立空间连线。':'连线模式：依次选择两张卡片。') : '' ;document.querySelector('[data-action="connect"]').classList.toggle('active',mode==='connect');document.querySelector('[data-action="knowledge"]').classList.toggle('active',state.showKnowledge);}
function applyView(){const v=board().view;v.zoom=Math.max(.3,Math.min(2,v.zoom||1));$('world').style.transform=`translate(${v.x}px,${v.y}px) scale(${v.zoom})`;$('zoom-value').textContent=Math.round(v.zoom*100)+'% ﹀';}
function renderEdges(){const b=board(),lines=[];const edge=(a,z,type)=>{if(!a||!z)return;const aw=a.w||(a.type==='board'?300:a.type==='note'?158:200),zw=z.w||(z.type==='board'?300:z.type==='note'?158:200),right=z.x>=a.x,x1=a.x+(right?aw:0),y1=a.y+(a.type==='board'?125:(a.h||230)/2),x2=z.x+(right?0:zw),y2=z.y+(z.type==='board'?125:(z.h||230)/2);lines.push(`<path class="edge ${type}" d="M${x1},${y1} C${x1+80},${y1} ${x2-80},${y2} ${x2},${y2}"/>`);};if(state.showSpace)b.edges.forEach(e=>edge(b.nodes.find(n=>n.id===e.from),b.nodes.find(n=>n.id===e.to),'space'));if(state.showKnowledge){const used=new Set();b.nodes.filter(n=>n.doc).forEach(a=>{const d=state.docs[a.doc];for(const m of d.body.matchAll(/\[\[([^\]|]+)(?:\|[^\]]+)?\]\]/g)){b.nodes.filter(n=>n.doc&&state.docs[n.doc].title===m[1]).forEach(z=>{const key=[a.id,z.id].sort().join(':');if(a.id!==z.id&&!used.has(key)){used.add(key);edge(a,z,'knowledge');}});}});}$('edges').innerHTML=lines.join('');}
function renderSelection(){const n=node();$('selection-bar').innerHTML=n?`<span>${esc(n.type==='board'?state.boards[n.board].title:n.type==='article'?state.docs[n.doc].title:n.title||'灵感图片')}</span>${n.type==='board'?'<button data-nav="'+esc(n.board)+'" data-testid="enter-selected-board">进入 Board ↗</button>':''}<button data-action="move">移到画板 ↗</button>${n.type==='board'?'<button data-action="rename-selected">重命名</button>':''}${n.type==='board'&&state.boards[n.board].iconMode==='ai'?'<button data-regenerate-board="'+esc(n.board)+'" data-testid="regenerate-board-icon">重新生成图标</button>':''}<button data-action="remove">移除入口</button><button data-action="clear">×</button>`:'';}
function select(id){const n=board().nodes.find(n=>n.id===id);if(!n)return;if(mode==='connect'){if(!connectStart){connectStart=id;toast('已选起点，再选择终点');}else if(connectStart!==id){if(!board().edges.some(e=>(e.from===connectStart&&e.to===id)||(e.from===id&&e.to===connectStart))){board().edges.push({from:connectStart,to:id});save();toast('已添加手动画板连线');}connectStart=null;mode='select';}render();return;}selected=id;document.querySelectorAll('#nodes > .node').forEach(el=>el.classList.toggle('selected',el.dataset.node===selected));renderSelection();}
function navigate(id){if(!state.boards[id]||!closeModal())return;state.currentBoard=id;selected=null;connectStart=null;mode='select';$('preview').innerHTML='';$('popover').innerHTML='';save();render();}
function openPreview(did){const d=state.docs[did];if(!d)return;$('preview').innerHTML=`<div class="preview-header"><small>MARKDOWN · 示例原文</small><button data-action="close-preview" aria-label="关闭文章预览">×</button></div><h2>${esc(d.title)}</h2><div class="path">${esc(d.path)}</div><pre>${esc(d.body)}</pre><div class="actions"><button class="btn" data-edit="${esc(d.id)}" data-testid="edit-document">编辑正文</button><button class="btn" data-add-doc="${esc(d.id)}">再放一张引用</button></div><p class="path">所有卡片引用同一份正文。本原型尚未接入真实 Vault。</p><div>${Object.values(state.docs).filter(x=>x.id!==d.id&&(d.body.includes('[['+x.title+']]')||x.body.includes('[['+d.title+']]'))).map(x=>`<button class="relation" data-preview="${esc(x.id)}">↗ ${esc(x.title)}</button>`).join('')}</div>`;}
function setModal(title,content,large=false){if(!closeModal())return false;modalFocus=document.activeElement;$('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="close" data-action="close-modal" aria-label="关闭对话框">×</button></div>${content}</section></div>`;setTimeout(()=>document.querySelector('.modal input,.modal textarea,.modal button')?.focus(),0);return true;}
function dirty(){return editSnapshot&&($('edit-title')?.value!==editSnapshot.title||$('edit-body')?.value!==editSnapshot.body);}
function closeModal(force=false){if(!force&&dirty()&&!confirm('正文尚未保存。要放弃这次修改吗？'))return false;previewRequest?.abort();previewToken++;$('modal-root').innerHTML='';editSnapshot=null;modalFocus?.focus?.();return true;}
let chosenTheme='product',renameTarget=null,iconMode='ai',chosenIcon=null,manualIcon=false,sessionApiKey='',previewIcon={status:'pending'},previewRequest=null,previewToken=0;
function iconCatalog(){return window.BoardIconCatalog?.icons||[];}
function matchIcon(name){const q=name.trim().toLowerCase(),icons=iconCatalog();let best=null,score=0;for(const icon of icons){for(const key of icon.keywords||[]){if(q.includes(key.toLowerCase())&&key.length>score){score=key.length;best=icon.id;}}}return best||'folder';}
function iconSvg(name,id){const icon=iconCatalog().find(i=>i.id===id)||iconCatalog().find(i=>i.id==='folder');return icon?.svg||'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 20H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h5l2 2h9a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2Z" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function defaultFolder(name,id,status='default'){return `<div class="folder-art custom-folder default-folder"><img src="assets/default-folder.png" alt="玻璃文件夹"><span class="folder-sticker">${iconSvg(name,id)}</span>${status==='generating'?'<span class="icon-loading">正在生成…</span>':status==='failed'?'<span class="icon-loading failed">生成失败 · 默认图标</span>':''}</div>`;}
function openBoardDialog(id=null){renameTarget=id;chosenTheme=id?state.boards[id].theme:'product';iconMode=id?(state.boards[id].iconMode||'default'):'ai';chosenIcon=id?state.boards[id].iconId:null;manualIcon=id?(state.boards[id].iconManual===undefined?!!state.boards[id].iconId:state.boards[id].iconManual===true):false;previewIcon=id&&state.boards[id].iconUrl?{status:'generated',url:state.boards[id].iconUrl,title:state.boards[id].title}:{status:'pending'};
if(!setModal(id?'重命名 Board':'新建 Board',`<p class="board-intro">根据名称匹配图标，或联网生成图片并保存到本地。</p><div class="icon-tabs" role="tablist"><button data-icon-mode="default" data-testid="mode-default" role="tab">默认图标</button><button data-icon-mode="ai" data-testid="mode-ai" role="tab">AI 生成</button></div><label class="board-name-label" for="new-board-title">Board 名称</label><input id="new-board-title" data-testid="new-board-title" aria-label="画板名称" placeholder="给画板起个名字" value="${id?esc(state.boards[id].title):''}"><small class="name-help">输入名称后自动匹配主题，也可以手动选择贴纸。</small><div class="icon-preview-row"><div id="board-icon-preview"></div><div class="icon-preview-info"><h3 id="icon-preview-title"></h3><span id="icon-status" role="status"></span><p id="icon-description"></p><div id="icon-preview-actions"></div><small class="icon-save-note" id="icon-save-note">生成的图片保存在本地，离线也能使用</small></div></div><div id="icon-picker"></div><div id="icon-service-panel"></div><div class="modal-foot board-modal-foot"><small>创建在「${esc(renameTarget?state.boards[state.boards[renameTarget].parent]?.title||'我的桌面':board().title)}」中</small><div><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="create-board" data-testid="create-board">${id?'保存修改':'创建 Board'}</button></div></div>`,true))return;document.querySelector('.modal').classList.add('board-modal');$('new-board-title').addEventListener('input',()=>{previewRequest?.abort();previewToken++;if(!manualIcon)chosenIcon=matchIcon($('new-board-title').value);if(previewIcon.title!==$('new-board-title').value.trim())previewIcon={status:'pending'};renderIconPreview();});renderIconPreview();}
function renderIconPreview(){if(!$('board-icon-preview'))return;const name=$('new-board-title').value.trim()||'新的 Board';if(!manualIcon)chosenIcon=matchIcon(name);document.querySelectorAll('[data-icon-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.iconMode===iconMode);b.setAttribute('aria-selected',String(b.dataset.iconMode===iconMode));});const ready=iconMode==='ai'&&previewIcon.status==='generated'&&previewIcon.title===name;$('board-icon-preview').innerHTML=ready?`<div class="folder-art custom-folder"><img src="${esc(previewIcon.url)}" alt="${esc(name)}的 AI 图标"></div>`:defaultFolder(name,chosenIcon);$('icon-preview-title').textContent=iconMode==='ai'?'AI 主题图标':'默认文件夹 · 开源贴纸';$('icon-status').textContent=iconMode==='default'?'已匹配':({pending:'待生成',generating:'生成中',generated:'已生成',failed:'生成失败'}[previewIcon.status]||'待生成');$('icon-status').className='icon-status '+(iconMode==='default'?'generated':previewIcon.status);$('icon-description').textContent=iconMode==='default'?(iconCatalog().find(i=>i.id===chosenIcon)?.label||'文件夹')+' · 来自本地图标库':previewIcon.status==='failed'?previewIcon.error||'请检查图像服务配置。':'点击创建时联网生成；也可以先预览效果。';$('icon-save-note').textContent=iconMode==='default'?'统一文件夹样式，无需联网':'生成的图片保存在本地，离线也能使用';$('icon-preview-actions').innerHTML=iconMode==='default'?'<button class="btn" data-action="icon-picker" data-testid="icon-picker">选择贴纸</button>':`<button class="btn" data-action="preview-ai" data-testid="generate-icon" ${previewIcon.status==='generating'?'disabled':''}>${ready?'↻ 重新生成':'生成预览'}</button><button class="icon-config-link" data-action="icon-service" data-testid="configure-ai">配置图像服务</button>${previewIcon.status==='failed'||!hasAIConfig()?'<button class="icon-config-link" data-action="use-default" data-testid="use-default">用默认图标继续</button>':''}`;}
function iconPicker(){if($('icon-picker').innerHTML){$('icon-picker').innerHTML='';return;}$('icon-picker').innerHTML=`<div class="icon-picker-grid">${iconCatalog().map(i=>`<button data-icon="${esc(i.id)}" data-testid="icon-${esc(i.id)}" aria-label="${esc(i.label)}">${i.svg}<span>${esc(i.label)}</span></button>`).join('')}</div><small class="icon-license">Lucide · ISC；部分源自 Feather（MIT）· 已保存开源许可证</small>`;}
function hasAIConfig(){return !!(sessionApiKey.trim()||state.imageService?.useServerKey);}
function iconService(){const config=state.imageService||{};$('icon-service-panel').innerHTML=`<div class="icon-service-form"><h3>图像服务配置</h3><label>服务地址<input id="ai-base-url" data-testid="ai-base-url" value="${esc(config.baseUrl||'https://api.openai.com/v1')}" aria-label="图像服务地址"></label><label>模型<input id="ai-model" data-testid="ai-model" value="${esc(config.model||'gpt-image-1')}" aria-label="图像模型"></label><label>API Key<input id="ai-api-key" data-testid="ai-api-key" type="password" autocomplete="off" value="${esc(sessionApiKey)}" aria-label="图像服务 API Key"></label><small>密钥只保留在本次会话内存。生成会联网并产生服务费用；图片落在本地原型目录。</small><button class="btn" data-action="save-ai-config" data-testid="save-ai-config">保存本次配置</button></div>`;}
function saveAIConfig(){sessionApiKey=$('ai-api-key').value.trim();state.imageService={baseUrl:$('ai-base-url').value.trim(),model:$('ai-model').value.trim()};save();$('icon-service-panel').innerHTML='';renderIconPreview();toast('配置已保存，密钥仅留在当前会话');}
async function requestIcon(name,force=false,signal){const config=state.imageService||{};const response=await fetch(force?'/api/board-icon/regenerate':'/api/board-icon',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,theme:chosenTheme,service:{baseUrl:config.baseUrl||'https://api.openai.com/v1',model:config.model||'gpt-image-1',apiKey:sessionApiKey},force}),signal});let data;try{data=await response.json();}catch(_){throw Error('请使用支持 AI 图标的本地原型服务打开页面');}if(!response.ok||!data.url)throw Error(data.error?.message||'图片生成失败');if(!/^\/assets\/generated-icons\/[a-zA-Z0-9._-]+$/.test(data.url))throw Error('图像服务返回的本地图片地址无效');return data;}
async function previewAI(){const name=$('new-board-title').value.trim();if(!name)return toast('先填写 Board 名称');if(!hasAIConfig()){previewIcon={status:'failed',error:'尚未配置图像服务。可以配置后生成，或用默认图标继续。'};renderIconPreview();iconService();return;}previewRequest?.abort();previewRequest=new AbortController();const token=++previewToken,input=$('new-board-title');previewIcon={status:'generating',title:name};renderIconPreview();try{const result=await requestIcon(name,true,previewRequest.signal);if(token!==previewToken||iconMode!=='ai'||$('new-board-title')!==input||input.value.trim()!==name)return;previewIcon={status:'generated',title:name,url:result.url,model:result.model};renderIconPreview();}catch(error){if(error.name==='AbortError'||token!==previewToken||iconMode!=='ai'||$('new-board-title')!==input||input.value.trim()!==name)return;previewIcon={status:'failed',title:name,error:error.message};renderIconPreview();}}
async function regenerateBoardIcon(id){const sub=state.boards[id];if(!sub)return;if(!hasAIConfig()){openBoardDialog(id);previewIcon={status:'failed',error:'请先配置本次会话的图像服务密钥。'};renderIconPreview();iconService();return;}sub.iconStatus='generating';save();render();try{const result=await requestIcon(sub.title,true);if(!state.boards[id])return;sub.iconUrl=result.url;sub.iconStatus='generated';sub.iconModel=result.model;delete sub.iconError;save();render();toast('主题图标已重新生成并保存到本地');}catch(error){sub.iconStatus='failed';sub.iconError=error.message;save();render();toast('图标生成失败，保留现有图标');}}
function revealInBoard(b,n){const top=210+b.view.y+n.y*b.view.zoom;if(top<235)b.view.y+=235-top;const left=b.view.x+n.x*b.view.zoom;if(left<35)b.view.x+=35-left;const right=b.view.x+(n.x+(n.type==='board'?300:n.w||200))*b.view.zoom;if(right>1495)b.view.x-=right-1495;const bottom=210+b.view.y+(n.y+(n.type==='board'?303:n.h||240))*b.view.zoom;if(bottom>860)b.view.y-=bottom-860;}
function addPosition(type='article'){const b=board(),i=b.nodes.length;if(b.id==='home'&&type==='board'){const k=b.nodes.filter(n=>n.type==='board').length;return {x:230+(k%3)*354,y:Math.floor(k/3)*327};}return {x:Math.max(40,(150+(i%4)*285-b.view.x)/b.view.zoom),y:Math.max(0,(35+Math.floor(i/4)*290-b.view.y)/b.view.zoom)};}
function createBoard(){const title=$('new-board-title').value.trim();if(!title){toast('请填写画板名称');return;}if(iconMode==='ai'&&!hasAIConfig()&&!(previewIcon.status==='generated'&&previewIcon.title===title)&&!(renameTarget&&state.boards[renameTarget].iconMode==='ai'&&state.boards[renameTarget].iconUrl)){previewIcon={status:'failed',error:'尚未配置图像服务。可以配置后生成，或用默认图标继续。'};renderIconPreview();return;}if(iconMode==='ai'&&previewIcon.status==='generating')return toast('预览图片正在生成，请稍候');const keepExisting=!!(renameTarget&&state.boards[renameTarget].iconMode===iconMode&&state.boards[renameTarget].iconUrl);let sub;if(renameTarget){sub=state.boards[renameTarget];sub.title=title;sub.theme=chosenTheme;}else{const id=newId('board');sub=state.boards[id]={id,title,parent:board().id,theme:chosenTheme,view:{x:0,y:0,zoom:1},nodes:[],edges:[]};const n={id:newId('folder'),type:'board',board:id,...addPosition('board')};board().nodes.push(n);selected=n.id;revealInBoard(board(),n);}sub.iconMode=iconMode;sub.iconId=chosenIcon;sub.iconManual=manualIcon;if(!keepExisting){delete sub.iconUrl;sub.iconStatus='default';}const cached=iconMode==='ai'&&previewIcon.status==='generated'&&previewIcon.title===title?clone(previewIcon):null;if(cached){sub.iconUrl=cached.url;sub.iconStatus='generated';sub.iconModel=cached.model;}const generate=iconMode==='ai'&&!cached&&!keepExisting;if(generate)sub.iconStatus='generating';closeModal(true);save();render();toast(generate?'画板已创建，正在联网生成主题图标':'画板已创建，点击名称或双击文件夹进入');if(generate){const name=title,theme=chosenTheme;requestIcon(name).then(result=>{if(!state.boards[sub.id]||sub.title!==name)return;sub.iconUrl=result.url;sub.iconStatus='generated';sub.iconModel=result.model;save();render();toast('主题图标已生成并保存到本地原型目录');}).catch(error=>{if(!state.boards[sub.id])return;sub.iconStatus='failed';sub.iconError=error.message;save();render();toast('图标生成失败，保留默认图标：'+error.message);});}}
function search(){if(!setModal('把文章放进画板',`<p>选择示例文章，卡片引用同一份正文。可重复放入不同画板。</p><input id="search-input" data-testid="search-input" aria-label="搜索文章" placeholder="搜索文章、关键词…"><div class="results" id="search-results"></div><div class="modal-foot"><small>仅操作示例库</small><button class="btn primary" data-action="create-document" data-testid="create-document">＋ 新建示例文章</button></div>`))return;searchResults('');$('search-input').addEventListener('input',e=>searchResults(e.target.value));}
function searchResults(q){q=q.toLowerCase().trim();const list=Object.values(state.docs).filter(d=>(d.title+' '+d.body).toLowerCase().includes(q));$('search-results').innerHTML=list.length?list.map(d=>`<button class="search-result" data-add-doc="${esc(d.id)}" data-testid="add-doc-${esc(d.id)}" aria-label="添加 ${esc(d.title)}"><span>${esc(d.title)}<small>${esc(d.path)}</small></span><b>＋</b></button>`).join(''):'<p>还没有这篇文章，可以新建。</p>';}
function addDoc(id){if(!state.docs[id])return;const n={id:newId('card'),type:'article',doc:id,...addPosition()};board().nodes.push(n);selected=n.id;revealInBoard(board(),n);closeModal(true);save();render();toast('引用已添加，原文保持同一来源');}
function editDoc(id){const d=state.docs[id];if(!setModal('编辑示例原文',`<p>保存后，同一文章在所有画板中的卡片都会同步。</p><input id="edit-title" data-testid="edit-title" aria-label="文章标题" value="${esc(d.title)}"><textarea id="edit-body" data-testid="edit-body" aria-label="Markdown 正文">${esc(d.body)}</textarea><div class="modal-foot"><button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-save-doc="${esc(id)}" data-testid="save-document">保存正文</button></div>`,true))return;editSnapshot={id,title:d.title,body:d.body};}
function saveDoc(id){const d=state.docs[id],title=$('edit-title').value.trim();if(!title)return toast('文章标题不能为空');if(Object.values(state.docs).some(x=>x.id!==id&&x.title===title))return toast('已有同名文章，请换一个标题');const old=d.title;d.title=title;d.body=$('edit-body').value.replace(/^# [^\n]*/, '# '+title);d.path='示例库/'+title+'.md';if(old!==title)Object.values(state.docs).forEach(x=>x.body=x.body.split('[['+old+']]').join('[['+title+']]'));closeModal(true);save();render();openPreview(id);toast('正文已保存，所有引用同步更新');}
function tree(){if($('popover').innerHTML){$('popover').innerHTML='';return;}const visited=new Set();let rows='';const visit=(id,depth)=>{if(visited.has(id)||!state.boards[id])return;visited.add(id);const b=state.boards[id],hidden=b.parent&&!state.boards[b.parent]?.nodes.some(n=>n.board===id);rows+=`<div class="tree-row" style="padding-left:${Math.min(depth,12)*14}px"><button data-nav="${esc(id)}" data-testid="tree-board-${esc(id)}">${depth?'▱':'⌂'} ${esc(b.title)}</button>${hidden?`<button class="restore" data-restore="${esc(id)}" data-testid="restore-${esc(id)}">恢复入口</button>`:''}</div>`;children(id).forEach(c=>visit(c.id,depth+1));};visit('home',0);Object.values(state.boards).filter(b=>!visited.has(b.id)).forEach(b=>visit(b.id,0));$('popover').innerHTML=`<div class="popover"><h2>所有画板</h2>${rows}<small>这里包含已隐藏入口的画板。移除入口保留画板与原文，可随时恢复。</small></div>`;}
function restore(id){const sub=state.boards[id],parent=state.boards[sub.parent]||state.boards.home;if(!parent.nodes.some(n=>n.board===id))parent.nodes.push({id:newId('folder'),type:'board',board:id,x:150+(parent.nodes.length%4)*300,y:35+Math.floor(parent.nodes.length/4)*290});sub.parent=parent.id;save();render();$('popover').innerHTML='';tree();toast('入口已恢复到「'+parent.title+'」');}
function moveDialog(){const n=node();if(!n)return toast('先选择要移动的文章或画板');const opts=Object.values(state.boards).map(b=>{const blocked=b.id===board().id||(n.type==='board'&&descendant(b.id,n.board));return `<option value="${esc(b.id)}" ${blocked?'disabled':''}>${esc(path(b.id).map(x=>x.title).join(' / '))}${blocked?'（不可移入）':''}</option>`;}).join('');setModal('移动到另一个画板',`<p>文章移动的是引用，原文保持不变。子画板会连同更深层级一起移动。</p><select id="move-target" data-testid="move-target" aria-label="目标画板">${opts}</select><div class="modal-foot"><small>不能把画板移到自己或自己的后代。</small><button class="btn primary" data-action="confirm-move" data-testid="confirm-move">移动卡片</button></div>`);}
function moveNode(n,target){const source=board(),dest=state.boards[target];if(!dest||dest.id===source.id)return false;if(n.type==='board'&&descendant(target,n.board)){toast('不能把画板移到自己或自己的后代');return false;}if(n.type==='board'&&dest.nodes.some(x=>x.board===n.board)){toast('目标画板已经有这个入口');return false;}source.nodes=source.nodes.filter(x=>x.id!==n.id);source.edges=source.edges.filter(e=>e.from!==n.id&&e.to!==n.id);n.x=dest.id==='home'&&n.type!=='board'?60:150+(dest.nodes.length%4)*285;n.y=dest.id==='home'&&n.type!=='board'?80:35+Math.floor(dest.nodes.length/4)*290;dest.nodes.push(n);revealInBoard(dest,n);if(n.type==='board')state.boards[n.board].parent=dest.id;selected=null;save();render();toast('已移到「'+dest.title+'」，原文保持不变');return true;}
function remove(){const n=node();if(!n)return toast('先选择要移除的卡片');board().nodes=board().nodes.filter(x=>x.id!==n.id);board().edges=board().edges.filter(e=>e.from!==n.id&&e.to!==n.id);selected=null;$('preview').innerHTML='';save();render();toast(n.type==='board'?'入口已隐藏，画板可在所有画板中找回':'引用已移除，示例原文保留');}
function settings(){setModal('画板设置',`<div class="setting-row"><span>知识链接 · 来自 [[双向链接]]</span><input type="checkbox" id="knowledge-check" ${state.showKnowledge?'checked':''} aria-label="显示知识虚线"></div><div class="setting-row"><span>画板连线 · 手动空间关系</span><input type="checkbox" id="space-check" ${state.showSpace?'checked':''} aria-label="显示手动实线"></div><p class="settings-note">这是可交互设计原型，使用示例 Markdown 与画板数据。${storageOk?'修改保存在本浏览器中。':'浏览器保存不可用，本次修改仅保留在当前页面。'}<br>尚未接入真实 Obsidian Vault；未来插件将文章保存在本地，画板只记录布局与引用。</p><div class="modal-foot"><button class="btn" data-action="import-v1" data-testid="import-v1">导入旧版示例数据</button><button class="btn" data-action="export">导出原型数据</button></div><div class="modal-foot"><button class="btn danger" data-action="reset">重置示例库</button><button class="btn primary" data-action="save-settings">保存设置</button></div>`);}
function importOld(){let old;try{old=JSON.parse(localStorage.getItem(OLD_KEY)||'null');}catch(_){return toast('旧版数据无法读取');}if(!old?.boards?.home||!old.docs)return toast('本浏览器中没有旧版示例数据');const ids={},docs={};Object.keys(old.boards).forEach(id=>ids[id]=newId('legacy-board'));Object.values(old.docs).forEach(d=>{const id=newId('legacy-doc');docs[d.id]=id;state.docs[id]={...d,id};});Object.values(old.boards).forEach(b=>{const id=ids[b.id],nodes=[];b.nodes.forEach(n=>{if(n.type==='column')n.docs.forEach((d,i)=>{if(docs[d])nodes.push({id:newId('legacy-card'),type:'article',doc:docs[d],x:n.x+i*220,y:n.y});});else if(n.type==='article'&&docs[n.doc])nodes.push({...n,id:newId('legacy-card'),doc:docs[n.doc]});else if(n.type==='board'&&ids[n.board])nodes.push({...n,id:newId('legacy-folder'),board:ids[n.board]});else if(n.type==='note')nodes.push({...n,id:newId('legacy-note')});});state.boards[id]={id,title:b.id==='home'?'旧版画板':b.title,parent:b.id==='home'?'home':ids[b.parent]||ids.home,theme:'reading',view:{x:0,y:0,zoom:1},nodes,edges:[]};});state.boards.home.nodes.push({id:newId('legacy-entry'),type:'board',board:ids.home,x:230,y:665});save();closeModal(true);render();toast('旧版数据已复制到「旧版画板」，旧版保存仍保留');}
function zoom(){setModal('画布缩放',`<p>拖动空白处平移；按住 Ctrl / ⌘ 滚轮缩放。</p><div class="modal-foot"><button class="btn" data-zoom="-0.1" data-testid="zoom-out">－ 缩小</button><button class="btn" data-action="reset-view">恢复视图</button><button class="btn" data-zoom="0.1" data-testid="zoom-in">＋ 放大</button></div>`);}
function changeZoom(delta){const v=board().view,z=v.zoom,next=Math.max(.35,Math.min(1.8,Math.round((z+delta)*100)/100));v.x=768-(768-v.x)/z*next;v.y=330-(330-v.y)/z*next;v.zoom=next;applyView();save();}
function action(a){switch(a){case'board':openBoardDialog();break;case'icon-picker':iconPicker();break;case'icon-service':iconService();break;case'save-ai-config':saveAIConfig();break;case'preview-ai':previewAI();break;case'use-default':iconMode='default';renderIconPreview();createBoard();break;case'article':openArticleLibrary();break;case'search':openContentSearch();break;case'tree':tree();break;case'rename':if(board().id==='home')toast('选择一个子画板后，可以重命名');else openBoardDialog(board().id);break;case'rename-selected':if(node()?.type==='board')openBoardDialog(node().board);break;case'create-board':createBoard();break;case'create-document':{const title=($('library-input')?.value||$('search-input')?.value||'').trim()||'一篇新的示例文章',id=newId('doc');let name=title,i=2;while(Object.values(state.docs).some(d=>d.title===name))name=title+' '+i++;state.docs[id]={id,title:name,path:'示例库/'+name+'.md',body:'# '+name+'\n\n从这里开始记录。'};addDoc(id);openPreview(id);break;}case'note':setModal('新建便利贴',`<input id="note-title" aria-label="便利贴标题" placeholder="标题"><textarea id="note-text" aria-label="便利贴内容" placeholder="记下一个想法…"></textarea><div class="modal-foot"><small>便利贴只保存在画板中。</small><button class="btn primary" data-action="save-note">放到画板</button></div>`);break;case'save-note':{const title=$('note-title').value.trim()||'新的想法';board().nodes.push({id:newId('note'),type:'note',title,text:$('note-text').value,...addPosition()});save();closeModal(true);render();break;}case'select':mode='select';connectStart=null;render();break;case'connect':mode=mode==='connect'?'select':'connect';connectStart=null;render();break;case'knowledge':state.showKnowledge=!state.showKnowledge;save();render();toast(state.showKnowledge?'知识链接已显示':'知识链接已隐藏');break;case'clear':selected=null;render();break;case'move':moveDialog();break;case'confirm-move':{const n=node();if(n&&moveNode(n,$('move-target').value))closeModal(true);break;}case'remove':remove();break;case'close-modal':closeModal();break;case'close-preview':$('preview').innerHTML='';break;case'settings':settings();break;case'save-settings':state.showKnowledge=$('knowledge-check').checked;state.showSpace=$('space-check').checked;save();closeModal(true);render();break;case'import-v1':importOld();break;case'zoom':zoom();break;case'zoom-less':changeZoom(-.1);break;case'reset-view':board().view={x:0,y:0,zoom:1};save();render();closeModal(true);break;case'reset':if(confirm('重置这份原型的示例库？本浏览器中的新版修改会被清除。')){state=clone(initial);selected=null;closeModal(true);$('preview').innerHTML='';$('popover').innerHTML='';save();render();}break;case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),el=document.createElement('a');el.href=url;el.download='obsidian-visual-board-v2.json';el.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}}
document.addEventListener('click',e=>{if(suppressClick)return;const t=e.target;let el;if((el=t.closest('[data-action]'))){action(el.dataset.action);return;}if((el=t.closest('[data-nav]'))){navigate(el.dataset.nav);return;}if((el=t.closest('[data-select]'))){select(el.dataset.select);return;}if((el=t.closest('[data-move]'))){select(el.dataset.move);moveDialog();return;}if((el=t.closest('[data-icon-mode]'))){iconMode=el.dataset.iconMode;previewRequest?.abort();previewToken++;previewIcon={status:'pending'};$('icon-picker').innerHTML='';renderIconPreview();return;}if((el=t.closest('[data-icon]'))){chosenIcon=el.dataset.icon;manualIcon=true;$('icon-picker').innerHTML='';renderIconPreview();return;}if((el=t.closest('[data-theme]'))){chosenTheme=el.dataset.theme;document.querySelectorAll('.theme').forEach(x=>x.classList.toggle('selected',x.dataset.theme===chosenTheme));return;}if((el=t.closest('[data-add-doc]'))){addDoc(el.dataset.addDoc);return;}if((el=t.closest('[data-edit]'))){editDoc(el.dataset.edit);return;}if((el=t.closest('[data-regenerate-board]'))){regenerateBoardIcon(el.dataset.regenerateBoard);return;}if((el=t.closest('[data-save-doc]'))){saveDoc(el.dataset.saveDoc);return;}if((el=t.closest('[data-preview]'))){openPreview(el.dataset.preview);return;}if((el=t.closest('[data-restore]'))){restore(el.dataset.restore);return;}if((el=t.closest('[data-zoom]'))){changeZoom(Number(el.dataset.zoom));return;}if((el=t.closest('[data-node]'))){const n=board().nodes.find(x=>x.id===el.dataset.node);select(el.dataset.node);if(mode!=='connect'&&n?.doc)openPreview(n.doc);return;}if(t.classList.contains('modal-backdrop'))closeModal();});
$('canvas').addEventListener('dblclick',e=>{const el=e.target.closest('[data-node]'),n=el&&board().nodes.find(x=>x.id===el.dataset.node);if(n?.type==='board')navigate(n.board);else if(n?.doc)editDoc(n.doc);});
$('canvas').addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button')||mode==='connect')return;const el=e.target.closest('[data-node]'),n=el&&board().nodes.find(x=>x.id===el.dataset.node);const v=board().view;gesture={kind:n?'node':'pan',el,n,startX:e.clientX,startY:e.clientY,x:n?n.x:v.x,y:n?n.y:v.y,moved:false,pointerId:e.pointerId,captured:false};});
$('canvas').addEventListener('pointermove',e=>{if(!gesture)return;const g=gesture,dx=(e.clientX-g.startX)/sceneScale,dy=(e.clientY-g.startY)/sceneScale;if(Math.abs(dx)+Math.abs(dy)>5)g.moved=true;if(!g.moved)return;if(!g.captured){$('canvas').setPointerCapture(g.pointerId);g.captured=true;}if(g.kind==='node'){g.n.x=g.x+dx/board().view.zoom;g.n.y=g.y+dy/board().view.zoom;g.el.style.left=g.n.x+'px';g.el.style.top=g.n.y+'px';g.el.classList.add('dragging');document.querySelectorAll('.folder').forEach(x=>x.classList.remove('drop-target'));const hit=dropTarget(g.n);if(hit)document.querySelector(`[data-node="${CSS.escape(hit.id)}"]`)?.classList.add('drop-target');renderEdges();}else{board().view.x=g.x+dx;board().view.y=g.y+dy;applyView();}});
function dropTarget(n){const cx=n.x+(n.type==='board'?150:100),cy=n.y+100;return [...board().nodes].reverse().find(t=>t.type==='board'&&t.id!==n.id&&cx>t.x&&cx<t.x+300&&cy>t.y&&cy<t.y+250);}
function endGesture(){if(!gesture)return;const g=gesture;gesture=null;if(g.moved){suppressClick=true;if(g.kind==='node'){const dest=dropTarget(g.n);if(dest){if(!moveNode(g.n,dest.board)){g.n.x=g.x;g.n.y=g.y;render();}}else{selected=g.n.id;save();render();}}else save();setTimeout(()=>suppressClick=false,180);}}
$('canvas').addEventListener('pointerup',endGesture);window.addEventListener('pointerup',endGesture);$('canvas').addEventListener('pointercancel',()=>{if(gesture?.kind==='node'){gesture.n.x=gesture.x;gesture.n.y=gesture.y;}gesture=null;render();});
$('canvas').addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();changeZoom(e.deltaY<0?.1:-.1);}}, {passive:false});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('modal-root').innerHTML){closeModal();return;}$('popover').innerHTML='';$('preview').innerHTML='';mode='select';connectStart=null;selected=null;render();}if(e.key==='Tab'&&$('modal-root').innerHTML){const els=[...document.querySelectorAll('.modal button:not(:disabled),.modal input,.modal textarea,.modal select')],first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='Enter'&&e.target.id==='new-board-title'){e.preventDefault();createBoard();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-node]')){e.preventDefault();const n=board().nodes.find(n=>n.id===e.target.dataset.node);if(n?.type==='board')navigate(n.board);else{select(n.id);if(n?.doc)openPreview(n.doc);}}if((e.key==='Delete'||e.key==='Backspace')&&selected&&!e.target.closest('input,textarea,select')&&!$('modal-root').innerHTML){e.preventDefault();remove();}});
window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue='';}});window.addEventListener('resize',fit);fit();render();
